// ── TLS Socket (std.net.tls) ────────────────────────────────
#include <openssl/ssl.h>
#include <openssl/err.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <netdb.h>
#include <arpa/inet.h>
#include <errno.h>

typedef struct {
    int fd;
    SSL_CTX* ctx;
    SSL* ssl;
} GorgetTlsSocket;

static const char* __gorget_tls_last_error = NULL;

static GorgetTlsSocket gorget_tls_connect(const char* host, int64_t port) {
    __gorget_tls_last_error = NULL;
    GorgetTlsSocket sock = {-1, NULL, NULL};

    // DNS resolution
    char port_str[16];
    snprintf(port_str, sizeof(port_str), "%lld", (long long)port);
    struct addrinfo hints, *res, *rp;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;
    int err = getaddrinfo(host, port_str, &hints, &res);
    if (err != 0) {
        __gorget_tls_last_error = gai_strerror(err);
        return sock;
    }

    // TCP connect
    int fd = -1;
    for (rp = res; rp != NULL; rp = rp->ai_next) {
        fd = socket(rp->ai_family, rp->ai_socktype, rp->ai_protocol);
        if (fd < 0) continue;
        if (connect(fd, rp->ai_addr, rp->ai_addrlen) == 0) break;
        close(fd);
        fd = -1;
    }
    freeaddrinfo(res);
    if (fd < 0) {
        __gorget_tls_last_error = "TCP connection failed";
        return sock;
    }

    // SSL setup
    SSL_CTX* ctx = SSL_CTX_new(TLS_client_method());
    if (!ctx) {
        close(fd);
        __gorget_tls_last_error = "SSL_CTX_new failed";
        return sock;
    }
    SSL_CTX_set_default_verify_paths(ctx);

    SSL* ssl = SSL_new(ctx);
    if (!ssl) {
        SSL_CTX_free(ctx);
        close(fd);
        __gorget_tls_last_error = "SSL_new failed";
        return sock;
    }

    SSL_set_fd(ssl, fd);
    SSL_set_tlsext_host_name(ssl, host);  // SNI

    if (SSL_connect(ssl) != 1) {
        __gorget_tls_last_error = "TLS handshake failed";
        SSL_free(ssl);
        SSL_CTX_free(ctx);
        close(fd);
        return (GorgetTlsSocket){-1, NULL, NULL};
    }

    // Verify certificate
    long verify_result = SSL_get_verify_result(ssl);
    if (verify_result != X509_V_OK) {
        __gorget_tls_last_error = X509_verify_cert_error_string(verify_result);
        SSL_shutdown(ssl);
        SSL_free(ssl);
        SSL_CTX_free(ctx);
        close(fd);
        return (GorgetTlsSocket){-1, NULL, NULL};
    }

    return (GorgetTlsSocket){fd, ctx, ssl};
}

static const char* gorget_tls_last_error(void) {
    return __gorget_tls_last_error;
}

static GorgetArray gorget_tls_read(GorgetTlsSocket* sock, int64_t n) {
    GorgetArray arr = gorget_array_new(sizeof(uint8_t));
    if (n <= 0 || !sock->ssl) return arr;
    uint8_t* buf = (uint8_t*)malloc((size_t)n);
    int got = SSL_read(sock->ssl, buf, (int)n);
    if (got > 0) {
        arr.data = buf;
        arr.len = (size_t)got;
        arr.cap = (size_t)n;
    } else {
        free(buf);
    }
    return arr;
}

static GorgetArray gorget_tls_read_exact(GorgetTlsSocket* sock, int64_t n) {
    GorgetArray arr = gorget_array_new(sizeof(uint8_t));
    if (n <= 0 || !sock->ssl) return arr;
    uint8_t* buf = (uint8_t*)malloc((size_t)n);
    size_t total = 0;
    while (total < (size_t)n) {
        int got = SSL_read(sock->ssl, buf + total, (int)((size_t)n - total));
        if (got <= 0) break;
        total += (size_t)got;
    }
    if (total == (size_t)n) {
        arr.data = buf;
        arr.len = (size_t)n;
        arr.cap = (size_t)n;
    } else {
        free(buf);
    }
    return arr;
}

static int64_t gorget_tls_write(GorgetTlsSocket* sock, const GorgetArray* data) {
    if (!sock->ssl || data->len == 0) return 0;
    size_t total = 0;
    while (total < data->len) {
        int sent = SSL_write(sock->ssl, (uint8_t*)data->data + total, (int)(data->len - total));
        if (sent <= 0) return -1;
        total += (size_t)sent;
    }
    return (int64_t)total;
}

static int64_t gorget_tls_write_str(GorgetTlsSocket* sock, const char* s) {
    if (!sock->ssl || !s) return 0;
    size_t len = strlen(s);
    size_t total = 0;
    while (total < len) {
        int sent = SSL_write(sock->ssl, s + total, (int)(len - total));
        if (sent <= 0) return -1;
        total += (size_t)sent;
    }
    return (int64_t)total;
}

static const char* gorget_tls_read_line(GorgetTlsSocket* sock) {
    if (!sock->ssl) return "";
    size_t cap = 256, len = 0;
    char* buf = (char*)malloc(cap);
    while (1) {
        char c;
        int got = SSL_read(sock->ssl, &c, 1);
        if (got <= 0) break;
        if (len + 1 >= cap) {
            cap *= 2;
            buf = (char*)realloc(buf, cap);
        }
        buf[len++] = c;
        if (c == '\n') break;
    }
    buf[len] = '\0';
    // Strip trailing \r\n
    while (len > 0 && (buf[len-1] == '\n' || buf[len-1] == '\r')) {
        buf[--len] = '\0';
    }
    return buf;
}

static void gorget_tls_close(GorgetTlsSocket* sock) {
    if (sock->ssl) {
        SSL_shutdown(sock->ssl);
        SSL_free(sock->ssl);
        sock->ssl = NULL;
    }
    if (sock->ctx) {
        SSL_CTX_free(sock->ctx);
        sock->ctx = NULL;
    }
    if (sock->fd >= 0) {
        close(sock->fd);
        sock->fd = -1;
    }
}


// ── Byte Buffer Helpers (std.bytes) ─────────────────────────

// Convert a str to Vector[uint8]
static inline GorgetArray gorget_bytes_from_str(const char* s) {
    GorgetArray arr = gorget_array_new(sizeof(uint8_t));
    if (s) {
        size_t len = strlen(s);
        for (size_t i = 0; i < len; i++) {
            uint8_t b = (uint8_t)s[i];
            gorget_array_push(&arr, &b);
        }
    }
    return arr;
}

// Convert Vector[uint8] to a null-terminated str
static inline const char* gorget_bytes_to_str(const GorgetArray* arr) {
    size_t len = arr->len;
    char* s = (char*)malloc(len + 1);
    if (len > 0) memcpy(s, arr->data, len);
    s[len] = '\0';
    return s;
}

// Convert a hex string to Vector[uint8]
static inline GorgetArray gorget_bytes_from_hex(const char* hex) {
    GorgetArray arr = gorget_array_new(sizeof(uint8_t));
    if (!hex) return arr;
    size_t len = strlen(hex);
    for (size_t i = 0; i + 1 < len; i += 2) {
        char buf[3] = { hex[i], hex[i+1], '\0' };
        uint8_t b = (uint8_t)strtoul(buf, NULL, 16);
        gorget_array_push(&arr, &b);
    }
    return arr;
}

// Write a big-endian uint32 at offset into Vector[uint8]
static inline void gorget_bytes_write_u32_be(GorgetArray* arr, int64_t offset, int64_t value) {
    if (offset < 0 || (size_t)(offset + 4) > arr->len) {
        fprintf(stderr, "gorget: panic: bytes_write_u32_be: offset %lld out of bounds (len %zu)\n", (long long)offset, arr->len);
        exit(1);
    }
    uint8_t* p = (uint8_t*)arr->data + offset;
    uint32_t v = (uint32_t)value;
    p[0] = (v >> 24) & 0xFF;
    p[1] = (v >> 16) & 0xFF;
    p[2] = (v >> 8) & 0xFF;
    p[3] = v & 0xFF;
}

// Read a big-endian uint32 from offset in Vector[uint8]
static inline int64_t gorget_bytes_read_u32_be(const GorgetArray* arr, int64_t offset) {
    if (offset < 0 || (size_t)(offset + 4) > arr->len) {
        fprintf(stderr, "gorget: panic: bytes_read_u32_be: offset %lld out of bounds (len %zu)\n", (long long)offset, arr->len);
        exit(1);
    }
    const uint8_t* p = (const uint8_t*)arr->data + offset;
    return (int64_t)(((uint32_t)p[0] << 24) | ((uint32_t)p[1] << 16) | ((uint32_t)p[2] << 8) | (uint32_t)p[3]);
}

// Concatenate two Vector[uint8]
static inline GorgetArray gorget_bytes_concat(const GorgetArray* a, const GorgetArray* b) {
    GorgetArray arr = gorget_array_new(sizeof(uint8_t));
    size_t total = a->len + b->len;
    if (total > 0) {
        arr.data = malloc(total * sizeof(uint8_t));
        arr.cap = total;
        if (a->len > 0) memcpy(arr.data, a->data, a->len);
        if (b->len > 0) memcpy((uint8_t*)arr.data + a->len, b->data, b->len);
        arr.len = total;
    }
    return arr;
}

// Slice a Vector[uint8] from start to end (exclusive)
static inline GorgetArray gorget_bytes_slice(const GorgetArray* arr, int64_t start, int64_t end) {
    GorgetArray out = gorget_array_new(sizeof(uint8_t));
    if (start < 0) start = 0;
    if (end > (int64_t)arr->len) end = (int64_t)arr->len;
    if (start >= end) return out;
    size_t count = (size_t)(end - start);
    out.data = malloc(count * sizeof(uint8_t));
    out.cap = count;
    memcpy(out.data, (uint8_t*)arr->data + start, count);
    out.len = count;
    return out;
}

// Generate random bytes using /dev/urandom
static inline GorgetArray gorget_random_bytes(int64_t n) {
    GorgetArray arr = gorget_array_new(sizeof(uint8_t));
    if (n <= 0) return arr;
    arr.data = malloc((size_t)n);
    arr.cap = (size_t)n;
    arr.len = (size_t)n;
    FILE* f = fopen("/dev/urandom", "rb");
    if (!f) {
        fprintf(stderr, "gorget: panic: cannot open /dev/urandom\n");
        exit(1);
    }
    if (fread(arr.data, 1, (size_t)n, f) != (size_t)n) {
        fprintf(stderr, "gorget: panic: short read from /dev/urandom\n");
        fclose(f);
        exit(1);
    }
    fclose(f);
    return arr;
}

// Write a big-endian uint16 at offset
static inline void gorget_bytes_write_u16_be(GorgetArray* arr, int64_t offset, int64_t value) {
    if (offset < 0 || (size_t)(offset + 2) > arr->len) {
        fprintf(stderr, "gorget: panic: bytes_write_u16_be: offset %lld out of bounds (len %zu)\n", (long long)offset, arr->len);
        exit(1);
    }
    uint8_t* p = (uint8_t*)arr->data + offset;
    uint16_t v = (uint16_t)value;
    p[0] = (v >> 8) & 0xFF;
    p[1] = v & 0xFF;
}

// Read a big-endian uint16 from offset
static inline int64_t gorget_bytes_read_u16_be(const GorgetArray* arr, int64_t offset) {
    if (offset < 0 || (size_t)(offset + 2) > arr->len) {
        fprintf(stderr, "gorget: panic: bytes_read_u16_be: offset %lld out of bounds (len %zu)\n", (long long)offset, arr->len);
        exit(1);
    }
    const uint8_t* p = (const uint8_t*)arr->data + offset;
    return (int64_t)(((uint16_t)p[0] << 8) | (uint16_t)p[1]);
}

// Convert Vector[uint8] to hex string
static inline const char* gorget_bytes_to_hex(const GorgetArray* arr) {
    size_t len = arr->len;
    char* s = (char*)malloc(len * 2 + 1);
    for (size_t i = 0; i < len; i++) {
        sprintf(s + i * 2, "%02x", ((uint8_t*)arr->data)[i]);
    }
    s[len * 2] = '\0';
    return s;
}

